ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-riskoff-20261003'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');activity=read(RUN/'activity.json');identity=read(RUN/'control-identity.json');fc=read(RUN/'forecast-summary.json')
 assert len(s)==v['accounts']==72 and rep['all_bytes_equal'] and rep['matched_files']==121 and not sel['passed']
 rows=[];base=[];annual=[];cost=[];ci=[];forecast=[]
 for n in ('RF_INFO','RF_RISK','RF_LEVEL','RF_PRICE','RF_INV','RF_TREND'):
  a=s['main-'+n+'-base']['metrics'];b=s['recent-'+n+'-base']['metrics'];base.append([n+(' · 기본' if n=='RF_INFO' else ' · 대조'),f"{a['return_pct']:+.2f}",f"{a['max_drawdown_pct']:.2f}",f"{b['return_pct']:+.2f}",f"{b['max_drawdown_pct']:.2f}",str(a['round_trips'])+' / '+str(b['round_trips'])])
  for p in ('main','recent'):
   key=p+'-'+n+'-base';e=s[key];m=e['metrics'];d=diag[key+'.json.gz']['sides'];annual.append([n,p,*[f"{e['annual'][y]['return_pct']:+.2f}" if y in e['annual'] else '해당 없음' for y in ('2022','2023','2024','2025','2026')]])
   cost.append([n,p,f"{m['gross_pnl']:+.2f}",f"{m['fees']+m['impact']:.2f}",f"{m['funding']:+.4f}",f"{m['mean_exposure']*100:.2f}",f"{m['realized_vol_pct']:.2f}",f"{d['BS']['net']:+.2f}",f"{d['BP']['net']:+.2f}"])
   for c in ('RF_RISK','RF_LEVEL','RF_PRICE','RF_TREND'):
    q=unc[p+'-'+n]['vs_'+c][1]['ci95'];ci.append([n,p,c,f'{q[0]:+.5f} ~ {q[1]:+.5f}'])
 for key,e in s.items():
  p,n,c=key.split('-');m=e['metrics'];rows.append({'strategy':n,'period':p,'scenario':c,**{k:m[k] for k in ('return_pct','max_drawdown_pct','realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure')}})
 for p,lags in fc.items():
  for lag,models in lags.items():
   for n,x in models.items():forecast.append([p,lag,n,x['n'],f"{x['mse']:.9f}",f"{x['sign_accuracy']*100:.2f}",x['nonnegative_riskoff_beta_weeks'] if x['nonnegative_riskoff_beta_weeks'] is not None else '해당 없음'])
 evidence={'build':'1003r1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'forecast_summary':fc,'scope':'BTC-only development; VIX weekly observed change beyond own price and realized risk, not BTC implied volatility or GFSI replication. Negative INFO/LEVEL slope required. CBOE current vintage with assumed D+2 availability, not first releases or unused OOS. No other-asset trading or accepted strategy','references':['https://doi.org/10.1016/j.qref.2018.04.003','https://doi.org/10.5089/9798400245411.001','https://www.cboe.com/tradable-products/vix/vix-historical-data','https://fred.stlouisfed.org/series/VIXCLS']}
 (DOWN/'btc-riskoff-evidence.json').write_bytes(canonical(evidence))
 with (DOWN/'btc-riskoff-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 with zipfile.ZipFile(DOWN/'btc-riskoff-evidence.zip','w',compression=zipfile.ZIP_STORED) as z:
  files=[(p,'run/'+p.name) for p in sorted(RUN.iterdir()) if p.is_file()]
  for n in ('btc_riskoff_study.py','test_btc_riskoff_study.py','verify_btc_riskoff_study.py','reproduce_btc_riskoff_study.py','audit_btc_riskoff_data.py','collect_btc_riskoff_data.py','btc_target_ledger.py'):files.append((ROOT/'tools'/n,'source/'+n))
  for namespace in ('riskoff','liquidity'):
   for n in ('independent-audit.json','prepare-audit.json'):files.append((ROOT/f'data/btc-{namespace}-20261003'/n,f'input-receipts/{namespace}/'+n))
  files.extend([(ROOT/'data/btc-venue-20261003/masks.json','input-receipts/btc-no-trade-mask.json'),(DOC/'EXPERIMENT_BTC_RISKOFF_20261003.md','source/EXPERIMENT_BTC_RISKOFF_20261003.md')])
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,3,0,0,0)),p.read_bytes())
  z.writestr(zipfile.ZipInfo('DATA-SOURCES.txt',(2026,10,3,0,0,0)),SOURCE_NOTE)
 html=HTML
 for token,value in [('BASE',table(['규칙','4년 수익','4년 DD','최근 수익','최근 DD','주/최근 보유구간'],base,'base-results')),('FORECAST',table(['기간','추가지연(일)','모형','공통주','MSE','방향정확도%','위험회피계수≥0주'],forecast,'forecast-results')),('ANNUAL',table(['규칙','기간','2022','2023','2024','2025','2026'],annual,'annual-results')),('COST',table(['규칙','기간','가격손익','비용','펀딩','평균노출%','연변동성%','롱 순손익','숏 순손익'],cost,'cost-results')),('CI',table(['규칙','기간','대조','일수익차95%구간'],ci,'uncertainty-results')),('MATRIX',table(['규칙','기간','조건','수익%','DD%','연변동성%','보유구간','비용'],[[r['strategy'],r['period'],r['scenario'],f"{r['return_pct']:+.2f}",f"{r['max_drawdown_pct']:.2f}",f"{r['realized_vol_pct']:.2f}",r['round_trips'],f"{r['fees']+r['impact']:.2f}"] for r in rows],'all-accounts'))]:html=html.replace('{{'+token+'}}',value)
 assert '{{' not in html
 (DOC/'btc-riskoff-research.html').write_text(html);p=DOC/'btc-web-research.html';old=p.read_text()
 if 'id="riskoff-followup"' not in old:p.write_text(old.replace('<h1>','<p id="riskoff-followup" class="boundary">추가72계좌: <a href="btc-riskoff-research.html">외부 위험회피 정보 검증 ↗</a></p><h1>',1))
 files=['btc-riskoff-research.html','btc-web-research.html','downloads/btc-riskoff-evidence.zip','downloads/btc-riskoff-evidence.json','downloads/btc-riskoff-summary.csv','EXPERIMENT_BTC_RISKOFF_20261003.md','BTC_WEB_RESEARCH_20261002.md'];out=ROOT/'runs/btc-riskoff-report-20261003';out.mkdir(exist_ok=True);(out/'public-manifest.json').write_bytes(canonical({n:{'sha256':sha((DOC/n).read_bytes()),'bytes':(DOC/n).stat().st_size} for n in files}));print(json.dumps({'accounts':len(rows),'files':len(files),'zip_bytes':(DOWN/'btc-riskoff-evidence.zip').stat().st_size}))
SOURCE_NOTE="""BTC-only external-risk information study. No other-asset trades.
VIX source: Chicago Board Options Exchange, daily CBOE Volatility Index: VIX [VIXCLS], official history https://www.cboe.com/tradable-products/vix/vix-historical-data ; CSV https://cdn.cboe.com/api/global/us_indices/daily_prices/VIX_History.csv ; FRED, Federal Reserve Bank of St. Louis https://fred.stlouisfed.org/series/VIXCLS . Retrieved 2026-10-03. CBOE raw SHA6edc3e3928c4b164b9e4ed1ec874e0ed53c7d52997557adebb7d6b7451db565a, FRED comparison SHA84f279d69e35eacf918b939875bf0ed7e0ad78d176cd289b24f2ebf364221510. Normalized observations SHA2531b2d4b51c4fe775dafbeac152ff579875b25d3a709c2d60250f7ab43ba82b.
Our transformations: latest six eligible observations, log last/first (5 observation intervals) and log last level, with D+2 assumed UTC availability, age<=5 and span<=14 days, plus lag7 stress. No weekend/holiday fill. These are derived research inputs, not a new CBOE index, BTC implied volatility, or original-vintage proof. CBOE/FRED same-source agreement is not independent reconstruction of SPX option methodology. Original data retain provider rights, not CC licensed here. No endorsement claimed.
Package: all 72 hypothetical accounts, derived features (no raw VIX value arrays), forecasts, plans, independent validation and blocked-replay hashes, input receipts and source/test/verify/replay/specification. Full provider CSVs and normalized VIX observation table are NOT redistributed, neither are paper PDFs. Reproduction needs the exact separately sourced raw CBOE/FRED snapshots, their specified data/btc-web-20261003 paths, and the normalization script. Current downloads may change; hashes distinguish versions.
BTC inputs remain the prior public BTC ZIP/checksum archive, common market canonical SHA9909be60d1d4db6b47f766de26894de9cbb55222530f9c3bbdbc19ef0899faa4, daily close/RV in prior liquidity daily.json.gz (canonical SHA2b7c5a957845d2df07c1d71f7cefb0da2c536cdeec598478e34a3340f5703c3b, available in the prior btc-liquidity-evidence.zip), and frozen spot-quality/no-trade masks. The repository layout, raw ZIPs/common inputs and shared Python dependencies are required separately. This is not a standalone execution environment. Old strategies and CS/AR were not rerun for this study. No individual addresses/wallets, private data, live account/service inputs or secrets.
"""
HTML='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self';script-src 'none';style-src 'self';img-src 'self' data:;connect-src 'none';object-src 'none';base-uri 'none';form-action 'none'"><title>BTC 외부 위험회피 검증</title><link rel="icon" href="assets/icon.svg"><link rel="stylesheet" href="assets/btc-continuation.css"></head><body><a class="skip" href="#results">결과로 이동</a><header><a href="./">BTC RESEARCH</a><nav><a href="btc-web-research.html">전체 연구 기록</a><a href="#downloads">검증 자료</a></nav></header><main><p class="eyebrow">BTC-ONLY · BUILD1003r1</p><h1>외부 위험회피 정보도<br>BTC 전략의 기준을 넘지 못했습니다.</h1><p class="lead">미국 옵션시장의 VIX 증가가 BTC 자체 가격·실현위험을 넘어 음의 선행 정보를 주는지 검정했습니다. 비용 후 수익·낙폭·최근 내구성·추가 예측오차가 사전 기준에 미달했습니다.</p><div class="facts"><article><b>72</b><span>조건별 가상계좌</span></article><article><b>기각</b><span>RF_INFO 기본 후보</span></article><article><b>121</b><span>파일 소켓차단 바이트 일치</span></article></div><p class="boundary">2022–2025와2026.01–08은 이미 본 개발 자료입니다. 새 OOS·원문전략 복제·인과 입증이 아닙니다. VIX는 BTC 예측의 외부 입력일 뿐, 다른 자산은 거래하지 않습니다.</p><section id="results"><h2>기본과 모든 대조군</h2><p>각1,000USDT,수익·최대낙폭(DD)은 %. TREND는 저장된 E_SPOT와 일별·주요회계가 같습니다.</p>{{BASE}}<p>기본 주 +45.13%·DD23.48%·연변동성15.03%·Sharpe0.694,최근 +0.89%·DD1.68%. 주 수익52.838713%·DD13.561952%·변동성13.343621%·Sharpe0.8과 최근 수익4.628391% 기준을 유지했습니다. 2022년 −4.86%도 보존합니다.</p><p>최근 수익은 새 발동0일로 기존 추세 대조와 같습니다. 이 수익을 새 정보의 성과로 세거나 유리한 LEVEL/INV를 기본으로 교체하지 않습니다.</p></section><section><h2>원문의 금융스트레스와 이번 지표는 다릅니다</h2><p>2018 원문은 Bloomberg 제공 BoA/Merrill Lynch 글로벌합성스트레스로 BTC 꼬리관계를 검정했습니다. 저자는 OOS 검정이라고 부르지만 구체 학습·배포시계와 비용 후 계좌를 이번에 재현한 것은 아닙니다. 중앙 분위 예측은 제한적이고 큰 상승·하락 꼬리 모두 관련돼 단일 안전자산/위험자산 규칙을 보증하지 않습니다.</p><p>2023 IMF의 기관 위험수요 경로는 초록만 확보했으며,공식 PDF405/403을 우회하지 않았습니다. 이번 VIX 변화의 단순 주간 회귀는 그 논문이나 유료 GFSI의 복제가 아닙니다.</p><p>VIX는 SPX/SPXW 옵션으로 만든30일 미국주식 기대변동성입니다. BTC 내재변동성·실현위험 정답·직접 매수자산·VIX 파생상품 정산가(SOQ)가 아닙니다. 옵션 원자료나 다른 자산을 거래하지 않았습니다.</p></section><section><h2>가용 시각·휴일·현재 빈티지를 구분했습니다</h2><p>공식 CBOE와 FRED의2019.01–2026.08 관측1,958개가 날짜·Decimal 종가에서 일치했습니다. 같은 원천의 배포 일치이지 독립 옵션산식 검증은 아닙니다. FRED 빈행41개는 관측으로 채우지 않았습니다.</p><p>미국 관측일 D를 D+2일00UTC에 이용 가능하다고 가정했습니다. 현행 VIX 정규장 배포는16:15ET까지지만 역사 CSV의 최초 게시·수신시각은 입증되지 않았습니다. 이번 CBOE에는10월2일 값,FRED에는10월1일 값까지만 보여 두 배포 시계가 다릅니다. 추가7일 지연도 최초 빈티지 문제를 해결하지 않습니다.</p><p>최신6관측으로5관측간격 로그변화와 로그수준을 따로 계산했습니다. 최신 관측은5달력일 이내·전체창14일 이내여야 하며,무효행을 건너뛰어 과거 정상값으로 채우지 않습니다. 주말/휴일 보간·0수익 삽입 없음. BTC는29연속완료일과 기존16무효일을 그대로 사용했습니다.</p><p>최신 공식 산식은2026년2월 문서이고2025년 bid/ask0 처리 변경 및 재공표 규칙을 포함합니다. 전체역사가 같은 방법·같은 당시 값이었다고 주장하지 않습니다.</p></section><section><h2>음의 위험회피 부호와 추가 정보</h2><p>INFO=BTC7/28일 가격변화+1/7/28일 로그 실현분산+VIX변화. RISK=같은5 BTC통제,LEVEL=통제+VIX수준,PRICE=가격2. 과거104달력주 안의 최소52공통유효주·최근1주 분리·달력1주 HAC를 고정했습니다. 무제약 회귀값은 모두 보존하되 INFO/LEVEL은 추가계수&lt;0·비용+SE·RISK 대비 같은 방향 추가분을 모두 만족해야 거래합니다.</p><p>기본 주30주210일발동,최근0주0일. 최근 INFO의34공통주 계수는 모두 음수였지만 나머지 발동 조건을 넘지 못했습니다. LEVEL은34주 모두 계수≥0였습니다. 부호 하나만 맞았다고 유용한 신호로 간주하지 않습니다.</p><p>공통201/34주. 주 MSE INFO0.005415841456 vs RISK0.005278241878·PRICE0.004772016980;최근 INFO0.004537699121 vs RISK0.004405027930·PRICE0.004307522722. 두 기간 모두 예측오차가 커졌습니다.</p><p>INFO 비용2배 +38.29% / +0.65%,추가1h +40.14% / +0.65%,추가24h +26.20% / −1.35%,자료7일 추가지연 +37.64% / −3.55%,위험10% +20.43% / +0.53%. 위험목표·창·관문을 바꾸지 않았습니다.</p><details><summary>예측과 위험회피 부호</summary>{{FORECAST}}</details><details><summary>연도별 수익</summary>{{ANNUAL}}</details><details><summary>롱숏·비용·펀딩·위험</summary>{{COST}}</details><details><summary>모든 대조군 차이의 불확실성</summary><p>14일 원형블록2,000회95%구간(%/일);7/28일은 JSON. 반복개발의 선택 문제를 제거하는 독립 입증이 아닙니다.</p>{{CI}}</details></section><section><h2>모든 비용·지연·위험 조건</h2><p>현물10bp/선물5bp+편도1.5bp 불리한 impact,실제 funding,수량/금액 최소치·5%p조절밴드·종료비용 포함. 위험20%/총명목상한1배. 실제호가·부분체결·과거규정·순간청산·세금·운영비는 미복원입니다.</p><details id="matrix"><summary>72계좌 전체 보기</summary>{{MATRIX}}</details></section><section id="proof"><h2>독립 검산·차단 재현</h2><p>19합성검사,공식2CSV의1,958 Decimal값·329BTC ZIP·58,056유효시간의 BTC분산·696주피처·1,908정규방정식 모형·30,672일판단·9,274폐형식 수량·52,281무거래·7,056실제펀딩·16,367이벤트·61,344일말을 검사했습니다. 시간DD·담보·연도·노출·선정·추세항등·180불확실성 구간 포함.</p><p>최대 계좌차2×10⁻¹¹USDT,모형차2.21×10⁻¹³. 121파일 소켓차단 바이트 일치. 사전b2f9b3b → 입력f724623 →19검사구현7e5b458 → 독립68b4de2. 검산 성공은 전략 성공이 아닙니다. 과거 CS/AR/전체전략은 재실행하지 않았습니다.</p></section><section id="downloads"><h2>검증 자료</h2><div class="downloads"><a download href="downloads/btc-riskoff-evidence.zip">72계좌·피처·검산 ZIP ↓</a><a download href="downloads/btc-riskoff-evidence.json">전체 수치·불확실성 JSON ↓</a><a download href="downloads/btc-riskoff-summary.csv">72조건 CSV ↓</a></div><p>VIX 출처: Chicago Board Options Exchange, CBOE Volatility Index: VIX [VIXCLS],<a href="https://www.cboe.com/tradable-products/vix/vix-historical-data">CBOE 공식 종가</a> 및 <a href="https://fred.stlouisfed.org/series/VIXCLS">FRED·세인트루이스 연은</a>,2026-10-03 확보. 자체 변환·모형·가상계좌이며 공급자의 보증이나 새 CBOE 지수가 아닙니다.</p><p><a href="EXPERIMENT_BTC_RISKOFF_20261003.md">성과 전 명세·자료 동결</a> · <a href="BTC_WEB_RESEARCH_20261002.md">원문 감사·실패 기록</a> · <a href="https://doi.org/10.1016/j.qref.2018.04.003">BTC 금융스트레스 원문</a></p><p>전체 원시 CBOE/FRED CSV·정규화 지수표·논문 PDF는 ZIP에 재배포하지 않습니다. 자체 피처·예측·전 계좌·검산과 입력 영수증/정확 SHA를 제공합니다. 원시 지수 스냅샷·공통 BTC 시장자료·이전 일집계·경로·의존성은 별도 필요하며 완전 독립 실행환경이 아닙니다.</p><p>아직 만족할 전략은 없습니다. 실거래·상시모의 서비스 없이 공개 연구만 수행합니다.</p></section><footer>BUILD1003r1 · BTC-only · 실거래 없음</footer></main></body></html>'''
